mapper.select:
SELECT sc.id, sc.type_name, sc.description, sc.price_multiplier, sc.create_time, sc.update_time, sc.create_user, sc.update_user, ca.name AS createUserName, ua.name AS updateUserName FROM service_category sc LEFT JOIN admin ca ON sc.create_user = ca.id LEFT JOIN admin ua ON sc.update_user = ua.id
AND sc.type_name LIKE CONCAT('%', #{typeName}, '%')
AND sc.price_multiplier >= #{minPriceMultiplier}
AND sc.price_multiplier <= #{maxPriceMultiplier}
AND sc.create_time >= #{createTimeStart}
AND sc.create_time <= #{createTimeEnd}
ORDER BY sc.create_time DESC
